//! Per-device signed command blobs.
//!
//! These are opaque, vendor-signed byte strings lifted from the Windows
//! driver. The sensor validates their signatures, so they cannot be
//! synthesised or altered - only replayed verbatim per device model.

pub struct DeviceBlobs {
    pub init_hardcoded: &'static str,
    pub init_hardcoded_clean_slate: &'static str,
    pub reset_blob: &'static str,
    pub db_write_enable: &'static str,
}

impl DeviceBlobs {
    pub fn init_hardcoded(&self) -> Vec<u8> {
        hex::decode(self.init_hardcoded).expect("built-in blob is valid hex")
    }
    pub fn init_hardcoded_clean_slate(&self) -> Vec<u8> {
        hex::decode(self.init_hardcoded_clean_slate).expect("built-in blob is valid hex")
    }
    pub fn reset_blob(&self) -> Vec<u8> {
        hex::decode(self.reset_blob).expect("built-in blob is valid hex")
    }
    pub fn db_write_enable(&self) -> Vec<u8> {
        hex::decode(self.db_write_enable).expect("built-in blob is valid hex")
    }
}

/// 138a:0090
pub static DEV_90: DeviceBlobs = DeviceBlobs {
    init_hardcoded: "",
    init_hardcoded_clean_slate: "",
    reset_blob: "",
    db_write_enable: "",
};

/// 138a:0097
pub static DEV_97: DeviceBlobs = DeviceBlobs {
    init_hardcoded: "",
    init_hardcoded_clean_slate: "",
    reset_blob: "",
    db_write_enable: "",
};

/// 138a:009d
pub static DEV_9D: DeviceBlobs = DeviceBlobs {
    init_hardcoded: "",
    init_hardcoded_clean_slate: "",
    reset_blob: "",
    db_write_enable: "",
};

/// 06cb:009a
pub static DEV_9A: DeviceBlobs = DeviceBlobs {
    init_hardcoded: "",
    init_hardcoded_clean_slate: "",
    reset_blob: "",
    db_write_enable: "",
};

/// Look up the blob set for a USB device ID.
pub fn blobs_for(vid: u16, pid: u16) -> Option<&'static DeviceBlobs> {
    match (vid, pid) {
        (0x138a, 0x0090) => Some(&DEV_90),
        (0x138a, 0x0097) => Some(&DEV_97),
        (0x138a, 0x009d) => Some(&DEV_9D),
        (0x06cb, 0x009a) => Some(&DEV_9A),
        _ => None,
    }
}
